@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

@base <http://example.org/onto/securities#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "Ontology modeling securities, financial instruments, bonds, equities, derivatives and funds as described in the source corpus." .

#################################################################
# CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "Financial Instrument" ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled; per IAS 32/39, any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Security" ;
    rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and which represents a claim on the issuer, tradable in financial markets." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:disjointWith fis:DerivativeInstrument ;
    rdfs:label "Cash Instrument" ;
    rdfs:comment "An instrument whose value is determined directly by the markets; includes securities (readily transferable) and instruments such as loans and deposits requiring agreement to transfer." .

fis:DerivativeInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:Underlying
    ] ;
    rdfs:label "Derivative" ;
    rdfs:comment "A contract whose value is derived from the performance of an underlier (asset, index, rate, or occurrence of an event); one of the three main categories of financial instruments along with equity and debt." .

fis:Underlying a owl:Class ;
    rdfs:label "Underlying" ;
    rdfs:comment "An item (asset, index, rate, currency, or event) on which a derivative's value depends." .

#### Debt vs Equity vs Derivative vs Hybrid split (three main categories + hybrid)

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasIssuer ;
        owl:someValuesFrom fis:Issuer
    ] ;
    rdfs:label "Debt Security" ;
    rdfs:comment "A negotiable financial instrument under which the issuer owes the holder a debt and is obliged to pay principal and interest; holder entitled to payment of principal and interest and other contractual rights." .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security" ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; entitles holder to pro rata control and residual claim on profits/assets, not entitled to fixed payment." .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security" ;
    rdfs:comment "A security combining some characteristics of both debt and equity securities." .

owl:AllDisjointClasses [
    owl:members ( fis:DebtSecurity fis:EquitySecurity fis:DerivativeInstrument )
] .

#################################################################
# Certificate / Form classifications
#################################################################

fis:SecurityForm a owl:Class ;
    rdfs:label "Security Form" ;
    rdfs:comment "Classification of a security by the way it is represented (certificated or non-certificated)." .

fis:CertificatedSecurity a owl:Class ;
    rdfs:subClassOf fis:SecurityForm ;
    rdfs:label "Certificated Security" ;
    rdfs:comment "A security represented by a physical certificate." .

fis:NonCertificatedSecurity a owl:Class ;
    rdfs:subClassOf fis:SecurityForm ;
    rdfs:label "Non-certificated Security" ;
    rdfs:comment "A security that is 'book entry only' or dematerialized, i.e. in electronic form, with no physical certificate." .

owl:AllDisjointClasses [ owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) ] .

fis:BearerSecurity a owl:Class ;
    rdfs:subClassOf fis:CertificatedSecurity ;
    rdfs:label "Bearer Security" ;
    rdfs:comment "A security that entitles the holder to rights under the security merely by holding it; completely negotiable, transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
    rdfs:subClassOf fis:CertificatedSecurity ;
    rdfs:label "Registered Security" ;
    rdfs:comment "A security that entitles the holder to rights only if they appear on a security register maintained by the issuer or an intermediary." .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:DividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Divided Security" ;
    rdfs:comment "Each divided security constitutes a separate asset, legally distinct from each other security in the same issue; each instrument is a separate debt/covenant of the issuer." .

fis:UndividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Undivided Security" ;
    rdfs:comment "The entire issue makes up one single asset, with each security a fractional part of the undivided whole; shares in secondary markets are always undivided." .

owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Fungible Security" ;
    rdfs:comment "A security in which all holdings of the security are treated identically and are interchangeable." .

#################################################################
# Stock / Equity hierarchy
#################################################################

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Stock" , "Share" ;
    rdfs:comment "Consists of all the shares by which ownership of a corporation or company is divided; a single share entitles fractional ownership of the corporation." .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Common Stock" , "Ordinary Share" , "Voting Share" ;
    rdfs:comment "A form of corporate equity ownership typically carrying voting rights and lowest priority to receive pay-outs from the company." .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:Stock , fis:HybridSecurity ;
    rdfs:label "Preferred Stock" , "Preference Share" ;
    rdfs:comment "A component of share capital with any combination of features not possessed by common stock, including properties of both equity and debt; senior to common stock but subordinate to bonds in claim; typically does not carry voting rights but has priority on dividends and liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasConversionRight ;
        owl:someValuesFrom fis:CommonStock
    ] ;
    rdfs:label "Convertible Preferred Stock" ;
    rdfs:comment "Preferred stock that includes the ability of the holder to convert the preferred shares into a fixed number of common shares." .

fis:CumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock" ;
    rdfs:comment "Requires that if a company fails to pay a dividend, it must make up for it later before paying common-stock dividends again; passed dividends accumulate as dividends in arrears." .

fis:NoncumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Noncumulative Preferred Stock" , "Straight Preferred Stock" ;
    rdfs:comment "A preferred stock lacking the cumulative feature; any dividends passed are lost if not declared." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:RestrictedStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Rule 144 Stock" , "Restricted Security" , "Control Security" ;
    rdfs:comment "Shares of stock subject to SEC Rule 144, acquired in unregistered form; subject to different resale rules than ordinary common or preferred stock." .

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Depositary Receipt" ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American Depositary Receipt" ;
    rdfs:comment "A depositary receipt listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European Depositary Receipt" ;
    rdfs:comment "A depositary receipt issued by European banks." .

fis:GlobalDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "Global Depositary Receipt" ;
    rdfs:comment "A depositary receipt issued by banks other than US or European issuers." .

#################################################################
# Bond hierarchy
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasMaturityDate ;
        owl:someValuesFrom xsd:date
    ] ;
    rdfs:label "Bond" ;
    rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at the maturity date plus interest (coupon); a form of loan or IOU." .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond" , "Perpetuity" , "Irredeemable Bond" ;
    rdfs:comment "A bond with no maturity date, also called a perpetuity." .

#### Issuer-based bond classification

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasIssuer ;
        owl:someValuesFrom fis:SovereignGovernment
    ] ;
    rdfs:label "Government Bond" , "Sovereign Bond" , "Treasury Bond" ;
    rdfs:comment "Medium or long term debt securities issued by sovereign governments or their agencies to support public spending." .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasIssuer ;
        owl:someValuesFrom fis:SupranationalOrganization
    ] ;
    rdfs:label "Supranational Bond" , "Supra" ;
    rdfs:comment "Represents the debt of international organizations such as the World Bank, the IMF, and regional multilateral development banks." .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasIssuer ;
        owl:someValuesFrom fis:LocalGovernment
    ] ;
    rdfs:label "Municipal Bond" ;
    rdfs:comment "A bond issued by state or local governments, or entities they create such as authorities and special districts, representing debt of sub-sovereign governmental units." .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasIssuer ;
        owl:someValuesFrom fis:Corporation
    ] ;
    rdfs:label "Corporate Bond" ;
    rdfs:comment "A bond issued by a corporation to raise financing for operations, mergers & acquisitions, or business expansion; represents the debt of commercial or industrial entities." .

owl:AllDisjointClasses [
    owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond )
] .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "Revenue Bond" ;
    rdfs:comment "A special type of municipal bond guaranteed solely by revenues from a specified revenue-generating entity; typically non-recourse." .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "General Obligation Bond" ;
    rdfs:comment "Principal and interest secured by the full faith and credit of the issuer, usually supported by taxing power; considered the most secure type of municipal bond." .

fis:AssessmentBond a owl:Class ;
    rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "Assessment Bond" ;
    rdfs:comment "Promises repayment based on property tax assessments of properties within the issuer's boundaries; a form of general obligation bond." .

owl:AllDisjointClasses [ owl:members ( fis:RevenueBond fis:GeneralObligationBond ) ] .

fis:WarBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "War Bond" ;
    rdfs:comment "A bond issued by a government to fund military operations and other expenditure during wartime." .

fis:ClimateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Climate Bond" , "Green Bond" ;
    rdfs:comment "A bond issued by a government or corporate entity to raise finance for climate change mitigation or adaptation projects." .

fis:HighYieldBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "High-Yield Bond" , "Junk Bond" ;
    rdfs:comment "Bonds rated below investment grade by credit rating agencies, due to uncertainty the issuer will pay interest or redeem at maturity; riskier, higher yield." .

fis:InvestmentGradeBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "Investment Grade Bond" , "High Grade Bond" ;
    rdfs:comment "Corporate bonds rated AAA, AA, A, or BBB." .

owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

fis:SubordinatedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Subordinated Bond" , "Junior Bond" ;
    rdfs:comment "A bond with lower priority than other (senior) bonds of the issuer in case of liquidation." .

fis:SeniorBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Senior Bond" ;
    rdfs:comment "A bond with priority of repayment ahead of subordinated bonds in bankruptcy." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:AssetPool
    ] ;
    rdfs:label "Asset-Backed Security" ;
    rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from a pool of assets other than real estate mortgages (e.g. consumer loans, auto loans, credit card receivables, student loans)." .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond" ;
    rdfs:comment "Backed by cash flows from mortgages or public sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .

fis:SocialImpactBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Social Impact Bond" ;
    rdfs:comment "An agreement for public sector entities to pay back private investors after meeting verified improved social outcome goals." .

#### Coupon-based bond classification

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond" ;
    rdfs:comment "Has interest payments (coupon), usually semi-annual, that remain constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note" , "Floater" ;
    rdfs:comment "Has a variable coupon linked to a reference rate of interest such as LIBOR or Euribor, recalculated periodically." .

fis:ZeroCouponBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasCouponRate ;
        owl:hasValue 0.0
    ] ;
    rdfs:label "Zero-Coupon Bond" , "Discount Bond" , "Deep Discount Bond" ;
    rdfs:comment "A bond in which the face value is repaid at maturity with no periodic interest payments; issued at a substantial discount to par value." .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond" , "Linker" , "Index-Linked Bond" ;
    rdfs:comment "Principal amount and interest payments are indexed to the level of consumer prices." .

owl:AllDisjointClasses [
    owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond )
] .

fis:LotteryBond a owl:Class ;
    rdfs:subClassOf fis:FixedRateBond ;
    rdfs:label "Lottery Bond" ;
    rdfs:comment "Issuer redeems randomly selected individual bonds within the issue according to a schedule, some at higher than face value." .

#### Optionality-based bond classification

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasEmbeddedOption ;
        owl:someValuesFrom fis:CallOption
    ] ;
    rdfs:label "Callable Bond" ;
    rdfs:comment "Gives the issuer the right to repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasEmbeddedOption ;
        owl:someValuesFrom fis:PutOption
    ] ;
    rdfs:label "Putable Bond" , "Retractable Bond" ;
    rdfs:comment "Gives the holder the right to force the issuer to repay the bond before the maturity date on put dates." .

fis:BulletBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Bullet Bond" ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

owl:AllDisjointClasses [ owl:members ( fis:CallableBond fis:PutableBond fis:BulletBond ) ] .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasConversionRight ;
        owl:someValuesFrom fis:CommonStock
    ] ;
    rdfs:label "Convertible Bond" , "Convertible Note" , "Convertible Debenture" ;
    rdfs:comment "A bond that the holder can convert into a specified number of shares of common stock in the issuing company or cash of equal value." .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    rdfs:label "Exchangeable Bond" ;
    rdfs:comment "Allows for exchange into shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Mandatory Convertible" ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .

fis:ContingentConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:label "Contingent Convertible Bond" , "CoCo" ;
    rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs, e.g. if asset value falls below guaranteed debt value." .

fis:PackagedConvertible a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Packaged Convertible" ;
    rdfs:comment "A straight bond and a call option/warrant wrapped together, where the two legs can be traded separately." .

fis:SyntheticConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Synthetic Convertible Bond" ;
    rdfs:comment "Synthetically structured convertible bond issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

#### Form-based bond classification

fis:BearerBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:BearerSecurity ;
    rdfs:label "Bearer Bond" ;
    rdfs:comment "An official certificate issued without a named holder; whoever possesses the certificate can claim the bond's value." .

fis:RegisteredBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:RegisteredSecurity ;
    rdfs:label "Registered Bond" ;
    rdfs:comment "A bond whose ownership is recorded by the issuer or transfer agent; opposite of a bearer bond." .

fis:BookEntryBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:NonCertificatedSecurity ;
    rdfs:label "Book-Entry Bond" ;
    rdfs:comment "A bond that does not have a paper certificate." .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) ] .

#### Money market instruments

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument" ;
    rdfs:comment "Short term debt instruments with original maturities of one year or less, highly liquid, sometimes called near cash." .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper" ;
    rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days, issued by large corporations to fund short-term obligations." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions with a specific fixed term before withdrawal without penalty." .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument , fis:GovernmentBond ;
    rdfs:label "Treasury Bill" ;
    rdfs:comment "Zero-coupon bonds issued by a national government that mature in one year or less, bought at a discount of par value." .

fis:RepurchaseAgreement a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Repurchase Agreement" ;
    rdfs:comment "Short-term loans arranged by selling securities to an investor with an agreement to repurchase them at a fixed price on a fixed date." .

#### Mortgage-backed securities

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:Mortgage
    ] ;
    rdfs:label "Mortgage-Backed Security" ;
    rdfs:comment "A type of asset-backed security secured by a mortgage or collection of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security" ;
    rdfs:comment "A pass-through MBS backed by mortgages on residential property." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security" ;
    rdfs:comment "A pass-through MBS backed by mortgages on commercial property." .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation" , "Pay-through Bond" ;
    rdfs:comment "A debt obligation collateralized by the assets it owns, divided into classes with different maturities and priorities for receipt of principal." .

fis:StrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Stripped Mortgage-Backed Security" ;
    rdfs:comment "Each mortgage payment is partly principal and partly interest; these components are separated to create SMBS." .

fis:InterestOnlyStrip a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "Interest-Only Strip" ;
    rdfs:comment "A bond with cash flows backed by the interest component of property owner's mortgage payments." .

fis:PrincipalOnlyStrip a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:label "Principal-Only Strip" ;
    rdfs:comment "A bond with cash flows backed by the principal repayment component of property owner's mortgage payments." .

owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:DebtObligationPool
    ] ;
    rdfs:label "Collateralized Debt Obligation" ;
    rdfs:comment "A type of structured asset-backed security backed by a pool of bonds or other debt obligations, sliced into tranches." .

fis:DebtObligationPool a owl:Class ;
    rdfs:subClassOf fis:AssetPool ;
    rdfs:label "Debt Obligation Pool" ;
    rdfs:comment "A pool of debt obligations (e.g. other asset-backed securities) backing a CDO." .

fis:AssetPool a owl:Class ;
    rdfs:label "Asset Pool" ;
    rdfs:comment "A pool of assets (e.g. loans, mortgages, receivables) backing an asset-backed security." .

fis:Mortgage a owl:Class ;
    rdfs:subClassOf fis:AssetPool ;
    rdfs:label "Mortgage" ;
    rdfs:comment "A loan secured by real estate, aggregated into pools for securitization." .

#################################################################
# Derivatives hierarchy
#################################################################

fis:LockProduct a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Lock Product" ;
    rdfs:comment "Derivatives (such as swaps, futures, or forwards) that obligate the contractual parties to the terms over the life of the contract." .

fis:OptionProduct a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Option Product" ;
    rdfs:comment "Derivatives that provide the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:Underlying
    ] ;
    rdfs:label "Forward" , "Forward Contract" ;
    rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an amount agreed upon today, not exchange-traded." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    rdfs:label "Future" , "Futures Contract" ;
    rdfs:comment "A standardized contract between two parties to buy or sell a specified asset of standardized quantity and quality for a price agreed upon today, with delivery at a specified future date; traded on a futures exchange." .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    rdfs:label "Swap" ;
    rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other party's financial instrument, over a notional principal amount." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Swap ) ] .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:OptionProduct ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasStrikePrice ;
        owl:someValuesFrom xsd:decimal
    ] ;
    rdfs:label "Option" ;
    rdfs:comment "A contract which gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option" ;
    rdfs:comment "An option that conveys to the owner the right to buy something at a certain price." .

fis:PutOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option" ;
    rdfs:comment "An option that conveys to the owner the right to sell something at a certain price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option" ;
    rdfs:comment "An option that may be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option" ;
    rdfs:comment "An option that may only be exercised on expiry." .

fis:BermudanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Bermudan Option" ;
    rdfs:comment "An option that may be exercised only on specified dates on or before expiration." .

fis:AsianOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Asian Option" ;
    rdfs:comment "An option whose payoff is determined by the average underlying price over some preset time period." .

fis:BarrierOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Barrier Option" ;
    rdfs:comment "An option whose general characteristic is that the underlying security's price must pass a certain level or barrier before it can be exercised." .

fis:BinaryOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Binary Option" ;
    rdfs:comment "An all-or-nothing option that pays the full amount if the underlying security meets the defined condition on expiration, otherwise expires worthless." .

fis:ExoticOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Exotic Option" ;
    rdfs:comment "Any of a broad category of options that may include complex financial structures." .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option , fis:HybridSecurity ;
    rdfs:label "Warrant" , "Equity Warrant" ;
    rdfs:comment "Long-dated options, generally traded over the counter, issued by the company allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

fis:StockOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:Stock
    ] ;
    rdfs:label "Stock Option" ;
    rdfs:comment "A class of option whose underlying security may be a stock index or an individual firm's stock." .

fis:StockDerivative a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:Stock
    ] ;
    rdfs:label "Stock Derivative" ;
    rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." .

fis:StockFuture a owl:Class ;
    rdfs:subClassOf fis:Future , fis:StockDerivative ;
    rdfs:label "Stock Future" ;
    rdfs:comment "A cash-settled futures contract on the value of a particular stock market index or individual firm's stock." .

fis:InterestRateSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap" ;
    rdfs:comment "A swap in which two counterparties exchange streams of periodic interest payments, typically fixed-rate for floating-rate, in one currency." .

fis:CurrencySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap" ;
    rdfs:comment "A swap in which two counterparties exchange streams of periodic interest payments in two different currencies." .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    owl:equivalentClass [
        a owl:Restriction ;
        owl:onProperty fis:hasUnderlying ;
        owl:someValuesFrom fis:ReferenceEntity
    ] ;
    rdfs:label "Credit Default Swap" ;
    rdfs:comment "A financial swap agreement whereby the seller compensates the buyer in the event of a loan default or other credit event, in exchange for a series of fee payments." .

fis:ReferenceEntity a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Reference Entity" ;
    rdfs:comment "The debt issuer or obligation whose creditworthiness underlies a credit default swap." .

fis:CommoditySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Commodity Swap" ;
    rdfs:comment "A swap exchanging cash flows based on the value of a commodity." .

fis:EquitySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Equity Swap" ;
    rdfs:comment "A swap exchanging cash flows based on the value of an equity or equity index." .

owl:AllDisjointClasses [
    owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap )
] .

fis:ExchangeTradedDerivative a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Exchange-Traded Derivative" ;
    rdfs:comment "Derivatives instruments that are traded via specialized derivatives exchanges or other exchanges." .

fis:OverTheCounterDerivative a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Over-the-Counter Derivative" ;
    rdfs:comment "Contracts that are traded (and privately negotiated) directly between two parties, without going through an exchange or other intermediary." .

owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

#################################################################
# Funds
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Investment Fund" ;
    rdfs:comment "An investment fund that pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund" ;
    rdfs:comment "An SEC-registered open-end investment company that pools money from many investors and invests in stocks, bonds, money-market instruments, or other securities." .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Exchange-Traded Fund" , "ETF" ;
    rdfs:comment "An exchange-traded investment product registered as an open-end investment company or unit investment trust; shares trade on exchanges at market prices that may differ from net asset value." .

fis:MoneyMarketFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Money Market Fund" ;
    rdfs:comment "Invests in liquid, short-term debt securities, cash, and cash equivalents." .

fis:BondFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Bond Fund" , "Fixed Income Fund" ;
    rdfs:comment "Invests primarily in bonds or other types of debt securities." .

fis:StockFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Stock Fund" , "Equity Fund" ;
    rdfs:comment "Invests primarily in stocks or equities." .

fis:HybridFund a owl:Class ;
    rdfs:subClassOf fis:MutualFund ;
    rdfs:label "Hybrid Fund" , "Balanced Fund" ;
    rdfs:comment "A fund investing in a blend of equities and fixed income." .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Index Fund" ;
    rdfs:comment "A passively managed fund that tracks the performance of an index, such as a stock market index or bond market index." .

fis:ActivelyManagedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Actively Managed Fund" ;
    rdfs:comment "A fund that seeks to outperform market indices through active security selection, generally charging higher fees." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Hedge Fund" ;
    rdfs:comment "Pools money from investors to try to make a profit, with more risky and flexible strategies than mutual funds and fewer regulations to protect investors." .

#################################################################
# Parties / Roles
#################################################################

fis:Party a owl:Class ;
    rdfs:label "Party" ;
    rdfs:comment "A natural or legal person participating in financial transactions." .

fis:Issuer a owl:Class ;
    rdfs:subClassOf fis:Party ;
    rdfs:label "Issuer" ;
    rdfs:comment "The company or other entity issuing a security; the entity obligated on a security or financial instrument." .

fis:SovereignGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Sovereign Government" ;
    rdfs:comment "A national government that issues sovereign/government bonds." .

fis:LocalGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Local Government" ;
    rdfs:comment "A sub-sovereign governmental unit such as a state, provincial, territorial, or municipal authority." .

fis:SupranationalOrganization a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Supranational Organization" ;
    rdfs:comment "An international organization such as the World Bank or IMF that issues supranational bonds." .

fis:Corporation a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Corporation" ;
    rdfs:comment "A commercial or industrial entity that issues corporate securities." .

owl:AllDisjointClasses [
    owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation )
] .

fis:Shareholder a owl:Class ;
    rdfs:subClassOf fis:Party ;
    rdfs:label "Shareholder" , "Stockholder" ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock in a joint stock company." .

fis:Bondholder a owl:Class ;
    rdfs:subClassOf fis:Party ;
    rdfs:label "Bondholder" ;
    rdfs:comment "The holder (creditor) of a bond, to whom the issuer owes principal and interest." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" ;
    rdfs:comment "Relates a security to its issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security ;
    rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:DerivativeInstrument ;
    rdfs:range fis:Underlying ;
    rdfs:label "has underlying" ;
    rdfs:comment "Relates a derivative to the underlier whose performance determines the derivative's value." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:DerivativeInstrument ;
    rdfs:label "is underlying of" .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Party ;
    rdfs:label "has holder" ;
    rdfs:comment "Relates a security to the party holding it." .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Party ;
    rdfs:range fis:Security ;
    rdfs:label "is holder of" .

fis:hasConversionRight a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:EquitySecurity ;
    rdfs:label "has conversion right" ;
    rdfs:comment "Relates a convertible security to the equity security into which it may be converted." .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Option ;
    rdfs:label "has embedded option" ;
    rdfs:comment "Relates a bond to an embedded option-like feature such as a call or put right." .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:AssetPool ;
    rdfs:label "has collateral" ;
    rdfs:comment "Relates a debt security to the asset or asset pool securing it." .

fis:hasPortfolio a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    rdfs:label "has portfolio" ;
    rdfs:comment "Relates an investment fund to the securities it holds in its portfolio." .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date" ;
    rdfs:comment "The date on which the principal (par value) of a bond is due to be repaid; a bond has a single, fixed maturity date." .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Nominal, principal, par, or face amount is the amount on which the issuer pays interest and which must be repaid at the end of the term." .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" ;
    rdfs:comment "The interest rate that the issuer pays to the holder; for fixed rate bonds this is fixed throughout the life of the bond." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price" ;
    rdfs:comment "The price at which the sale takes place under an option, specified at the time the parties enter into the option." .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:date ;
    rdfs:label "has expiration date" ;
    rdfs:comment "The last date the option can be exercised." .

fis:hasPremium a owl:DatatypeProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has premium" ;
    rdfs:comment "The price paid by the buyer to the seller for the right conferred by an option." .

fis:hasParValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has par value" ;
    rdfs:comment "A nominal accounting value assigned to a share of stock, used to represent equity on the balance sheet; not all stock has par value." .

fis:hasDividend a owl:DatatypeProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has dividend" ;
    rdfs:comment "A portion of a company's profit paid to shareholders; discretionary and not contractually guaranteed." .

fis:hasNotionalAmount a owl:DatatypeProperty ;
    rdfs:domain fis:Swap ;
    rdfs:range xsd:decimal ;
    rdfs:label "has notional amount" ;
    rdfs:comment "The nominal or face amount used to calculate payments on swaps and other derivatives; generally does not change hands." .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has yield to maturity" ;
    rdfs:comment "The total rate of return anticipated to be earned by an investor who buys a bond at a given market price, holds it to maturity, and receives all interest payments and the capital redemption on schedule." .

