@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "Models the taxonomy of financial instruments, securities, bonds, equities, derivatives, funds and related concepts as described in the supplied corpus." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties, e.g. cash, evidence of ownership/interest, a contractual right to receive or deliver currency, debt, equity or a derivative. Per IAS 32: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:FinancialAsset a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial asset" ;
    rdfs:comment "Per IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "financial liability" ;
    rdfs:comment "Per IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial instruments under potentially unfavourable conditions." .

fis:EquityInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "equity instrument" ;
    rdfs:comment "Per IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities." .

fis:FinancialLiability owl:disjointWith fis:EquityInstrument .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "cash instrument" ;
    rdfs:comment "Instrument whose value is determined directly by the markets; includes securities (readily transferable) and loans/deposits (require mutual agreement to transfer)." .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "loan" .

fis:Deposit a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "deposit" .

fis:Underlying a owl:Class ;
    rdfs:label "underlying" ;
    rdfs:comment "An item (the underlier) that a derivative references: a commodity, financial instrument, price index, currency, or interest rate." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlying .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlying ; rdfs:label "commodity" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlying ; rdfs:label "currency" .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Underlying ; rdfs:label "price index" .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Underlying ; rdfs:label "interest rate benchmark" .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Underlying ; rdfs:label "mortgage" .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" ;
    rdfs:comment "A tradable financial asset; a negotiable, fungible instrument representing a claim on an issuer that can be traded in financial markets." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:CashInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasMarket ; owl:someValuesFrom fis:Market ]
        )
    ] .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "derivative" ;
    rdfs:comment "A contract whose value depends on the performance of an underlier (commodity, financial instrument, index, currency or interest rate). Note: the corpus conflicts on whether derivatives are a subtype of security (US securities law view) or a category parallel to cash instruments/securities (financial-instrument taxonomy view); this ontology models derivatives as a sibling of CashInstrument/Security, per the more structurally detailed passage." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Underlying ]
        )
    ] .

fis:CashInstrument owl:disjointWith fis:Derivative .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:Security fis:Loan fis:Deposit ) .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Investor ;
    rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Investor ;
    rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlying ;
    rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:Derivative .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:EquitySecurity ;
    rdfs:label "has conversion target" .

fis:isConversionTargetOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasConversionTarget ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:HybridSecurity .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:Issuer ;
    rdfs:label "has reference entity" .

fis:isReferenceEntityOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasReferenceEntity ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:CreditDefaultSwap .

fis:hasPortfolio a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    rdfs:label "has portfolio" .

fis:isPortfolioOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasPortfolio ;
    rdfs:domain fis:Security ;
    rdfs:range fis:InvestmentFund .

fis:hasTrackedIndex a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:IndexFund ;
    rdfs:range fis:PriceIndex ;
    rdfs:label "has tracked index" .

fis:isTrackedIndexOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasTrackedIndex ;
    rdfs:domain fis:PriceIndex ;
    rdfs:range fis:IndexFund .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Dividend ;
    rdfs:label "has dividend" .

fis:isDividendOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasDividend ;
    rdfs:domain fis:Dividend ;
    rdfs:range fis:EquitySecurity .

fis:hasMarket a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Market ;
    rdfs:label "has market" .

fis:isMarketOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasMarket ;
    rdfs:domain fis:Market ;
    rdfs:range fis:Security .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Underlying ;
    rdfs:label "has collateral" .

fis:isCollateralOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCollateral ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:DebtSecurity .

fis:hasClearingHouse a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:ClearingHouse ;
    rdfs:label "has clearing house" .

fis:isClearingHouseOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasClearingHouse ;
    rdfs:domain fis:ClearingHouse ;
    rdfs:range fis:Derivative .

fis:hasCustodian a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Custodian ;
    rdfs:label "has custodian" .

fis:isCustodianOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCustodian ;
    rdfs:domain fis:Custodian ;
    rdfs:range fis:Security .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:date ;
    rdfs:label "has maturity date" .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Synonyms: nominal amount, principal, par value." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" .

fis:hasYield a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
    rdfs:label "has yield" .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
    rdfs:label "has strike price" .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:date ;
    rdfs:label "has expiration date" .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Future ; rdfs:range xsd:date ;
    rdfs:label "has delivery date" .

fis:hasTermInDays a owl:DatatypeProperty ;
    rdfs:domain fis:MoneyMarketInstrument ; rdfs:range xsd:integer ;
    rdfs:label "has term in days" .

fis:hasNotionalAmount a owl:DatatypeProperty ;
    rdfs:domain fis:Derivative ; rdfs:range xsd:decimal ;
    rdfs:label "has notional amount" .

fis:hasCallFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
    rdfs:label "has call feature" .

fis:hasPutFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
    rdfs:label "has put feature" .

fis:isStandardized a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ; rdfs:range xsd:boolean ;
    rdfs:label "is standardized" .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:string ;
    rdfs:label "has credit rating" .

fis:isExchangeTraded a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range xsd:boolean ;
    rdfs:label "is exchange traded" .

#################################################################
# SECURITY DIMENSIONS: certificate form, divisibility, fungibility,
# offering type
#################################################################

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "bearer security" ;
    rdfs:comment "Entitles the holder to rights merely by possession; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "registered security" ;
    rdfs:comment "Entitles the holder to rights only if recorded on a security register." .
fis:BookEntrySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "book-entry security" ;
    rdfs:comment "Non-certificated, electronic/dematerialized security." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "divided security" ;
    rdfs:comment "Each instrument constitutes a separate, legally distinct asset/debt." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "undivided security" ;
    rdfs:comment "The whole issue is one asset; each security is a fractional part of it." .
fis:DividedSecurity owl:disjointWith fis:UndividedSecurity .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "fungible security" ;
    rdfs:comment "All holdings are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "non-fungible security" .
fis:FungibleSecurity owl:disjointWith fis:NonFungibleSecurity .

fis:PubliclyOfferedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "publicly offered security" .
fis:PrivatelyPlacedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "privately placed security" ;
    rdfs:comment "Offered privately to a limited number of qualified investors; not publicly tradable." .
fis:PubliclyOfferedSecurity owl:disjointWith fis:PrivatelyPlacedSecurity .

#################################################################
# DEBT SECURITY / BOND HIERARCHY
#################################################################

fis:DebtSecurity a owl:Class ;
    rdfs:comment "Holder is entitled to payment of principal and interest; issued for a fixed term (except perpetual) and redeemable by the issuer. Simultaneously a financial asset to the holder and a financial liability to the issuer." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
        )
    ] .

fis:SeniorDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "senior debt security" ;
    rdfs:comment "Contractually prioritised over other unsecured debt in bankruptcy." .
fis:SubordinatedDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "subordinated debt security" .
fis:SeniorDebtSecurity owl:disjointWith fis:SubordinatedDebtSecurity .

fis:SecuredDebtSecurity a owl:Class ;
    rdfs:label "secured debt security" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Underlying ]
        )
    ] .
fis:UnsecuredDebtSecurity a owl:Class ;
    rdfs:label "unsecured debt security" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:maxCardinality "0"^^xsd:nonNegativeInteger ]
        )
    ] .
fis:SecuredDebtSecurity owl:disjointWith fis:UnsecuredDebtSecurity .

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "bond" ;
    rdfs:comment "A debt security under which the issuer owes the holder a debt and must provide cash flow, usually repayment of principal at maturity plus periodic interest (coupon)." .

fis:Debenture a owl:Class ;
    rdfs:label "debenture" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond fis:UnsecuredDebtSecurity )
    ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:SecuredDebtSecurity ;
    rdfs:label "covered bond" ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets which remain on the issuer's balance sheet, unlike asset-backed securities." .

# Bond classified by issuer type
fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "corporate bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "government bond" , "sovereign bond" , "treasury bond (generic)" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "municipal bond" , "muni" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "supranational bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:CorporateBond fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond ) .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "general obligation bond" ;
    rdfs:comment "Secured by the full faith and credit/taxing power of the issuer." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "revenue bond" ;
    rdfs:comment "Repaid solely from a specified stream of future income; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "assessment bond" ;
    rdfs:comment "Repayment based on property-tax assessments; generally considered a form of general obligation bond." .
fis:GeneralObligationBond owl:disjointWith fis:RevenueBond .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "high-yield bond" , "junk bond" ;
    rdfs:comment "Rated below investment grade." .
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "investment grade bond" , "high grade bond" .
fis:HighYieldBond owl:disjointWith fis:InvestmentGradeBond .

# US Treasury categories (maturity-based)
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "treasury bill" ;
    rdfs:comment "US Treasury zero-coupon money-market debt maturing in one year or less." .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "treasury note" ;
    rdfs:comment "US Treasury debt with maturity of two to ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "treasury bond (long bond)" ;
    rdfs:comment "US Treasury debt with the longest maturity, twenty to thirty years; distinct from the generic concept GovernmentBond." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond ) .

# Bond classified by coupon structure
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "fixed rate bond" ;
    rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "floating rate note" ;
    rdfs:comment "Coupon varies, linked to a money-market reference rate." .

fis:ZeroCouponBond a owl:Class ;
    rdfs:label "zero-coupon bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
    rdfs:comment "Pays no periodic interest; issued at a discount to face value, full principal paid at maturity." .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "inflation-indexed bond" , "linker" ;
    rdfs:comment "Principal and interest indexed to a consumer price index." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond ) .

fis:TreasuryInflationProtectedSecurity a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond, fis:InflationIndexedBond ;
    rdfs:label "Treasury Inflation-Protected Security" , "TIPS" .

fis:TreasuryBill rdfs:subClassOf fis:ZeroCouponBond, fis:MoneyMarketInstrument .

# Bond classified by embedded optionality
fis:CallableBond a owl:Class ;
    rdfs:label "callable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "Issuer may repay the bond before maturity on call dates." .

fis:PutableBond a owl:Class ;
    rdfs:label "putable bond" , "retractable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "Holder may force the issuer to repay the bond before maturity." .

fis:BulletBond a owl:Class ;
    rdfs:label "bullet bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue "false"^^xsd:boolean ]
        [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:BulletBond owl:disjointWith fis:CallableBond .
fis:BulletBond owl:disjointWith fis:PutableBond .

fis:PerpetualBond a owl:Class ;
    rdfs:label "perpetual bond" , "perpetuity" , "consol" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:comment "A bond with no maturity date; principal repaid only at the discretion of the borrower, if ever." .

fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:SubordinatedDebtSecurity ;
    rdfs:label "subordinated bond" .

#################################################################
# ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "asset-backed security" , "ABS" ;
    rdfs:comment "Umbrella term for a security backed by a pool of assets. Also used narrowly for securities backed by consumer loans (distinct from MBS and CDO). Both usages are modelled: AssetBackedSecurity is the broad umbrella; ConsumerAssetBackedSecurity captures the narrow sense." .

fis:ConsumerAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "consumer asset-backed security" ;
    rdfs:comment "Backed by consumer loans/receivables other than real estate (auto loans, credit cards, student loans, home equity loans)." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:label "mortgage-backed security" , "MBS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "collateralized debt obligation" , "CDO" ;
    rdfs:comment "Structured ABS backed by a pool of bonds or other debt obligations, sliced into tranches." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:ConsumerAssetBackedSecurity fis:MortgageBackedSecurity fis:CollateralizedDebtObligation ) .

fis:AssetBackedSecurity owl:disjointWith fis:CoveredBond .

fis:HomeEquityLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ; rdfs:label "home equity loan ABS" .
fis:AutoLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ; rdfs:label "auto loan ABS" .
fis:CreditCardABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ; rdfs:label "credit card ABS" .
fis:StudentLoanABS a owl:Class ; rdfs:subClassOf fis:ConsumerAssetBackedSecurity ; rdfs:label "student loan ABS" , "SLABS" .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "pass-through security" ;
    rdfs:comment "Interest and principal payments pass through to the holder pro rata." .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:PassThroughSecurity ;
    rdfs:label "residential mortgage-backed security" , "RMBS" .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:PassThroughSecurity ;
    rdfs:label "commercial mortgage-backed security" , "CMBS" .
fis:ResidentialMortgageBackedSecurity owl:disjointWith fis:CommercialMortgageBackedSecurity .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "collateralized mortgage obligation" , "CMO" , "pay-through bond" ;
    rdfs:comment "Debt obligation collateralized by assets it owns, divided into classes with different maturities/priorities; classified as debt, unlike pass-through securities." .
fis:PassThroughSecurity owl:disjointWith fis:CollateralizedMortgageObligation .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "stripped mortgage-backed security" , "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "interest-only strip" , "IO" .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "principal-only strip" , "PO" .
fis:InterestOnlyStrip owl:disjointWith fis:PrincipalOnlyStrip .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "money market instrument" ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:UnsecuredDebtSecurity ;
    rdfs:label "commercial paper" ;
    rdfs:comment "Unsecured promissory note with a fixed maturity usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:Deposit ;
    rdfs:label "certificate of deposit" , "CD" ;
    rdfs:comment "Time deposit sold by banks/thrifts/credit unions with a fixed term." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "banker's acceptance" .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "repurchase agreement" , "repo" ;
    rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price and date." .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security, fis:EquityInstrument ;
    rdfs:label "equity security" , "stock" , "share" ;
    rdfs:comment "A share of equity/ownership interest in an entity; holder has a residual claim after creditors and typically a pro-rata right to control and profits, but no fixed entitlement to payment (unlike debt securities)." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "common stock" , "ordinary share" , "voting share" ;
    rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "preferred stock" , "preference share" , "preferred share" ;
    rdfs:comment "Senior to common stock for dividends and liquidation but subordinate to bonds; generally considered a hybrid instrument. NOTE (conflict): under IAS 32 a mandatorily redeemable preference share is classified as a FinancialLiability rather than as an EquityInstrument, despite being market-labelled 'preferred equity'; this ontology follows the common/market classification as primary." .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "convertible preferred stock" , "convertible preference share" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

#################################################################
# HYBRID SECURITIES
#################################################################

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "hybrid security" ;
    rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preference shares, convertibles)." .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    rdfs:label "convertible bond" , "convertible note" , "convertible debenture" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:HybridSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "exchangeable bond" ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "mandatory convertible" ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .

fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:label "contingent convertible" , "CoCo" ;
    rdfs:comment "Automatically converts to equity if a pre-specified trigger event occurs." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) .
# NOTE: this tri-partition (US SEC classification: "debt, equity, derivatives") conflicts with
# the explicit existence of HybridSecurity, which "combines some of the characteristics of both
# debt and equity securities". HybridSecurity is modelled as a distinct, non-disjoint class so
# that instances such as ConvertibleBond (Bond+HybridSecurity) and PreferredStock
# (EquitySecurity+HybridSecurity) remain consistent.

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "depositary receipt" , "DR" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ] ) ] ;
    rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "American depositary receipt" , "ADR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "global depositary receipt" , "GDR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "European depositary receipt" , "EDR" .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:AmericanDepositaryReceipt fis:GlobalDepositaryReceipt fis:EuropeanDepositaryReceipt ) .

#################################################################
# DERIVATIVE SUBTYPES
#################################################################

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "forward" , "forward contract" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "Non-standardized, privately negotiated contract to buy/sell at a future date at a price agreed today." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "future" , "futures contract" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "Standardized contract traded on a futures exchange; cleared via a clearing house." .

fis:Forward owl:disjointWith fis:Future .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ] ) ] ;
    rdfs:comment "Conveys the right, but not the obligation, to buy or sell the underlying at the strike price on or before the expiration date." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "call option" ; rdfs:comment "Right to buy." .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "put option" ; rdfs:comment "Right to sell." .
fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "American option" ; rdfs:comment "May be exercised any time on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "European option" ; rdfs:comment "May only be exercised at expiry." .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "Bermudan option" ; rdfs:comment "May be exercised only on specified dates on or before expiration." .

[] a owl:AllDisjointClasses ;
    owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "binary option" ;
    rdfs:comment "All-or-nothing payoff profile." .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "warrant" ;
    rdfs:comment "A long-dated option, generally traded over the counter." .

fis:EquityWarrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
    rdfs:label "equity warrant" ;
    rdfs:comment "Option issued by a company allowing the holder to purchase a specific number of its shares at a specified price within a specified time." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:Derivative ;
    rdfs:label "swap" ;
    rdfs:comment "Two counterparties exchange cash flows (legs) of one financial instrument for those of another, over a notional principal amount." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "interest rate swap" .
